import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;

public class BufferedStreamRelayTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static ByteArrayOutputStream sink = new ByteArrayOutputStream();

    static long run(byte[] source, int bufferSize) {
        sink = new ByteArrayOutputStream();
        try {
            return BufferedStreamRelay.relay(new ByteArrayInputStream(source), sink, bufferSize);
        } catch (Exception e) {
            System.out.println("FAIL  relay threw " + e.getClass().getSimpleName());
            failures++;
            return -1L;
        }
    }

    public static void main(String[] args) {
        byte[] hello = "hello".getBytes(StandardCharsets.UTF_8);
        check("count with buffer 2", 5L, run(hello, 2));
        check("content with buffer 2", "hello", sink.toString(StandardCharsets.UTF_8));

        check("count with buffer 1", 5L, run(hello, 1));
        check("content with buffer 1", "hello", sink.toString(StandardCharsets.UTF_8));

        check("count with oversized buffer", 5L, run(hello, 4096));
        check("content with oversized buffer", "hello", sink.toString(StandardCharsets.UTF_8));

        byte[] big = new byte[5000];
        for (int i = 0; i < big.length; i++) {
            big[i] = (byte) (i % 251);
        }
        check("count for 5000 bytes", 5000L, run(big, 64));
        check("content for 5000 bytes", true, java.util.Arrays.equals(big, sink.toByteArray()));

        check("empty input", 0L, run(new byte[0], 8));
        check("empty output", 0, sink.toByteArray().length);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

